278	    public List<Pet> getPets() {
279	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
280	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
281	        return Collections.unmodifiableList(sortedPets);
282	    }
283	
